-- Fase 6: cobrança da Adaline às instituições (tabelas do legado) + colunas de contrato em INSTITUICAO.
-- Só para testes locais: em produção as tabelas já existem.
ALTER TABLE INSTITUICAO
  ADD CNPJ VARCHAR(20) NULL, ADD EMAIL_COBRANCA VARCHAR(200) NULL, ADD CEP VARCHAR(10) NULL, ADD UF VARCHAR(2) NULL,
  ADD CIDADE VARCHAR(100) NULL, ADD BAIRRO VARCHAR(100) NULL, ADD RUA VARCHAR(200) NULL, ADD NUMERO VARCHAR(20) NULL,
  ADD PLANO BIGINT NULL, ADD ALUNOS_QTD_MAX BIGINT NULL, ADD DATA_CADASTRO DATETIME NULL, ADD DATA_EDICAO DATETIME NULL;

CREATE TABLE AdalineCobranca (
  Id BIGINT AUTO_INCREMENT PRIMARY KEY, FkInstituicaoId BIGINT NOT NULL, FkSituacao VARCHAR(50) NOT NULL,
  DataVencimento DATETIME NOT NULL, FechamentoFatura DATETIME NULL, Ativos BIGINT NULL, Inativos BIGINT NULL,
  ValorPlano DECIMAL(10,2) NOT NULL DEFAULT 0, ValorExcedente DECIMAL(10,2) NULL, ValorBoletos DECIMAL(10,2) NULL,
  ValorTotal DECIMAL(10,2) NULL, DataPagamento DATETIME NULL, ValorPago DECIMAL(10,2) NULL,
  BoletoCloudToken2Via VARCHAR(200) NULL, BoletoCloudUrl2Via VARCHAR(500) NULL, FkUsuarioId BIGINT NULL,
  DataCadastro DATETIME NULL, DataEdicao DATETIME NULL
);
CREATE TABLE AdalineBoletoCloudExtrato (
  Id BIGINT AUTO_INCREMENT PRIMARY KEY, FkInstituicaoId BIGINT NOT NULL, FkContasReceberId BIGINT NOT NULL,
  TokenBoletoClound2Via VARCHAR(200) NULL, Valor DECIMAL(10,2) NOT NULL, DataVencimento DATETIME NOT NULL,
  DataCriacao DATETIME NOT NULL, DataEdicao DATETIME NOT NULL, Cobrado TINYINT(1) NOT NULL DEFAULT 0, FkCobrancaId BIGINT NULL
);
CREATE TABLE AdalineConfiguracao (Id BIGINT AUTO_INCREMENT PRIMARY KEY, BoletoNumDoc DECIMAL(18,0) NOT NULL, DataCadastro DATETIME NULL, DataEdicao DATETIME NULL);
INSERT INTO AdalineConfiguracao (BoletoNumDoc, DataCadastro) VALUES (5000, NOW());

